SELECT symbol, sentiment_available, fundamental_available, COUNT(*) AS n, MIN(sentiment_score) AS min_s, MAX(sentiment_score) AS max_s FROM crypto_ai.trade_signal WHERE interval_code = '1m' AND generated_at BETWEEN '2026-10-11 20:00:00' AND '2026-10-12 10:10:00' GROUP BY symbol, sentiment_available, fundamental_available ORDER BY symbol LIMIT 80;
SELECT id, symbol, generated_at, sentiment_available, sentiment_score, LEFT(explanation, 200) AS expl_200 FROM crypto_ai.trade_signal WHERE interval_code = '1m' AND sentiment_available = 1 AND generated_at BETWEEN '2026-10-11 20:50:00' AND '2026-10-11 21:00:00' ORDER BY generated_at LIMIT 20;